ICON_SIZE = 16


def menu_icon(name: str, color: str, disabled_color: str) -> QIcon:
    """이름의 아이콘을 color(비활성일 땐 disabled_color)로 칠한 QIcon. 화면 배율(DPR)을 반영한다."""
    from PyQt6.QtSvg import QSvgRenderer

    screen = QApplication.primaryScreen()
    ratio = screen.devicePixelRatio() if screen else 1.0
    size = round(ICON_SIZE * ratio)
    icon = QIcon()
    for mode, c in ((QIcon.Mode.Normal, color), (QIcon.Mode.Disabled, disabled_color)):
        pm = QPixmap(size, size)
        pm.fill(Qt.GlobalColor.transparent)
        painter = QPainter(pm)
        QSvgRenderer(QByteArray(_SVGS[name].replace("currentColor", c).encode())).render(painter)
        painter.end()
        pm.setDevicePixelRatio(ratio)
        icon.addPixmap(pm, mode)
    return icon
